CREATE TABLE knowledge_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,workspace_id uuid NOT NULL,title text NOT NULL,body text NOT NULL CHECK(length(body)<=20000),source_ref text NOT NULL,sha256 text NOT NULL,version integer NOT NULL DEFAULT 1,state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','published')),created_by uuid NOT NULL REFERENCES users(id),published_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz,UNIQUE(organization_id,id),FOREIGN KEY(organization_id,workspace_id)REFERENCES workspaces(organization_id,id));
CREATE INDEX knowledge_scope ON knowledge_documents(organization_id,workspace_id,state);
CREATE TABLE ai_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,workspace_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),profile text NOT NULL,profile_version integer NOT NULL DEFAULT 1,request_key text NOT NULL,input_digest text NOT NULL,source_snapshot jsonb NOT NULL,model text NOT NULL,state text NOT NULL CHECK(state IN('RUNNING','SUCCEEDED','UNKNOWN','FAILED')),output jsonb,usage jsonb,error_code text,created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,UNIQUE(organization_id,actor_id,request_key),FOREIGN KEY(organization_id,workspace_id)REFERENCES workspaces(organization_id,id));
